function speak(text){
 if(!text)return;
 if(window.NativeSpeech&&typeof window.NativeSpeech.speak==="function"){
   try{window.NativeSpeech.speak(String(text));return}catch(e){$("speechResult").textContent="Native audio bridge error: "+e.message}
 }
 if(!("speechSynthesis" in window)){$("speechResult").textContent="Chinese audio is unavailable. Enable a Mandarin text-to-speech voice on this device.";return}
 try{
  speechSynthesis.cancel();
  const u=new SpeechSynthesisUtterance(String(text));u.lang="zh-CN";u.rate=.82;
  const choose=()=>{const vs=speechSynthesis.getVoices();const v=vs.find(x=>/^zh(-|_)?CN/i.test(x.lang))||vs.find(x=>/^zh/i.test(x.lang));if(v)u.voice=v};
  choose();u.onerror=()=>{$("speechResult").textContent="Audio failed. Check that a Chinese speech voice is installed and enabled."};
  speechSynthesis.speak(u);
  if(speechSynthesis.getVoices().length===0)setTimeout(()=>{if(!speechSynthesis.speaking){choose();speechSynthesis.speak(u)}},350);
 }catch(e){$("speechResult").textContent="Could not play Chinese audio in this browser."}
}
window.onNativeSpeechResult=function(text){$("speechResult").textContent="Heard: "+text+" — compare it with the target phrase and try again if needed.";touchDay()};
window.onNativeSpeechError=function(message){$("speechResult").textContent=message||"Speech recognition failed. Check microphone permission and Chinese speech services."};
window.onNativeSpeechStarted=function(){$("speechResult").textContent="Listening… say the Chinese phrase now."};
window.addEventListener("error",e=>{const el=document.getElementById("speechResult");if(el)el.textContent="App script error: "+(e.message||"unknown JavaScript error")});

function normalizeSearch(value){return String(value??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim()}
function applyWordFilters(){
 const cat=$("vocabCategory")?.value||"all";
 const q=normalizeSearch($("vocabSearch")?.value||"");
 const selectedLevel=progress.settings.level||"beginner";
 const allowed=selectedLevel==="beginner"?[1]:selectedLevel==="intermediate"?[2,3]:[4];
 filteredWords=words.filter(w=>{
  const categoryMatch=cat==="all"||w.c===cat;
  const levelMatch=!w.hskLevel||allowed.includes(Number(w.hskLevel));
  const searchable=[w.h,w.p,w.m,w.e,w.eh,w.ep,w.c,w.en,w.vi].map(normalizeSearch).join(" ");
  return categoryMatch&&levelMatch&&(!q||searchable.includes(q));
 });
 wordIndex=0;
 renderWord();
}
function renderWord(){let w=filteredWords[wordIndex];if(!w){$("wordTag").textContent="NO MATCH";$("hanzi").textContent="找不到";$("pinyin").textContent="zhǎo bú dào";$("meaning").textContent="No matching words. Try another search."; $("meaning").classList.remove("hidden");$("example").classList.add("hidden");$("wordCounter").textContent="0 / 0";return;}$("wordTag").textContent=w.c.toUpperCase();$("hanzi").textContent=w.h;$("pinyin").textContent=w.p;$("meaning").textContent=w.m;$("example").textContent=w.e;$("meaning").classList.add("hidden");$("example").classList.add("hidden");$("revealBtn").textContent="Reveal meaning";$("wordCounter").textContent=`${wordIndex+1} / ${filteredWords.length}`;$("knownBtn").textContent=progress.known.includes(w.h)?"✓ Learned":"✓ I know this word"}
