function renderWriting(){let w=words[writeIndex%words.length];$("writeHanzi").textContent=w.h;$("writePinyin").textContent=w.p;$("writeMeaning").textContent=w.m;$("traceHanzi").textContent=[...w.h].join(" ");$("writeInput").value="";$("writePinyinInput").value="";$("writeFeedback").textContent=""}
function renderScenarios(){ $("scenarioList").innerHTML=scenarios.map((s,i)=>`<button class="scenario-btn ${i===scenarioIndex?'active':''}" data-scenario="${i}"><strong>${s.title}</strong><small>${s.cat}</small></button>`).join("");let s=scenarios[scenarioIndex];$("scenarioTag").textContent=s.cat.toUpperCase();$("scenarioTitle").textContent=s.title;$("scenarioDesc").textContent=s.desc;renderLines()}
function renderLines(){let s=scenarios[scenarioIndex],role=$("roleSelect").value;$("dialogueLines").innerHTML=s.lines.map((l,i)=>`<div class="line ${l[0]===role?'mine':''}"><span class="speaker">${l[0]}</span><div><strong>${l[1]}</strong><div class="line-pinyin">${l[2]}</div><div class="line-en">${l[3]}</div></div><button data-line="${i}" aria-label="Listen to line ${i+1}">🔊</button></div>`).join("")}
