function currentLessons(){const level=progress.settings.level||"beginner", selected=progress.settings.topics||topicDefs.map(t=>t.id);const ts=topicDefs.filter(t=>selected.includes(t.id));const topics=ts.length?ts:[topicDefs[0]];return Array.from({length:20},(_,i)=>{const topic=topics[i%topics.length],unit=Math.floor(i/5),pattern=lessonTitles[level][i%5];return {id:level+"-"+(i+1),n:i+1,level,topic,title:(progress.settings.language==="vi"?topic.vi:topic.en)+" · "+pattern,focus:pattern+" — "+topic.vi,topicId:topic.id,words:(()=>{const base=((levelTopicWords[level]&&levelTopicWords[level][topic.id])||topicWords[topic.id]||[]).map(h=>words.find(w=>w.h===h)).filter(Boolean);const pack=(hskLevelWords[level]||[]).map(row=>words.find(w=>w.h===row[0])).filter(w=>w&&((topic.cat||[]).includes(w.c)||topic.id==="social"));return [...new Map([...base,...pack].map(w=>[w.h,w])).values()].slice(0,8)})(),review:(i+1)%5===0,unit}})}
function renderTopicChoices(){const el=$("topicChoices");if(!el)return;el.innerHTML=topicDefs.map(t=>`<label class="topic-choice"><input type="checkbox" data-topic="${t.id}" ${(progress.settings.topics||[]).includes(t.id)?"checked":""}><span>${t.icon}</span><span><strong>${progress.settings.language==="vi"?t.vi:t.en}</strong><small>${t.en}</small></span></label>`).join("");el.querySelectorAll("[data-topic]").forEach(c=>c.addEventListener("change",()=>{let chosen=[...el.querySelectorAll("[data-topic]:checked")].map(x=>x.dataset.topic);if(!chosen.length){c.checked=true;chosen=[c.dataset.topic]}progress.settings.topics=chosen;save();renderLessons()}))}
let currentUnit=1;
function setPathScreen(screen){document.querySelectorAll("[data-path-screen]").forEach(b=>b.classList.toggle("active",b.dataset.pathScreen===screen));document.querySelectorAll("[data-screen]").forEach(el=>el.classList.toggle("active",el.dataset.screen===screen));}
function renderLevelSwitch(){document.querySelectorAll("[data-level]").forEach(b=>{b.classList.toggle("active",b.dataset.level===(progress.settings.level||"beginner"));b.setAttribute("aria-selected",String(b.dataset.level===(progress.settings.level||"beginner")))});}
function renderLessons(){const list=$("lessonList");if(!list)return;const lessons=currentLessons(),level=progress.settings.level||"beginner",completed=lessons.filter(l=>progress.lessons[l.id]).length;$("pathTitle").textContent=(levelDefs[level][progress.settings.language]||levelDefs[level].en)+" · 20 lessons";$("pathSub").textContent="Complete lessons in order; take a review test after every 5 lessons.";$("lessonProgress").textContent=completed+" / 20";$("lessonProgressBar").style.width=(completed/20*100)+"%";currentUnit=Math.min(4,Math.max(1,currentUnit));const units=$("unitSwitch");if(units){units.innerHTML=[1,2,3,4].map(u=>`<button type="button" class="unit-btn ${u===currentUnit?"active":""}" data-unit="${u}">Phần ${u}</button>`).join("");units.querySelectorAll("[data-unit]").forEach(b=>b.onclick=()=>{currentUnit=Number(b.dataset.unit);renderLessons()});$("unitCaption").textContent=`Phần ${currentUnit} · Bài ${(currentUnit-1)*5+1}–${currentUnit*5}`;}
list.innerHTML=lessons.filter(l=>l.unit===currentUnit-1).map(l=>{const done=!!progress.lessons[l.id],testDue=l.review&&completed>=l.n&& !progress.tests[level+"-"+l.n];return `<button class="lesson-row ${done?"completed":""}" data-lesson="${l.id}"><span class="lesson-number">${done?"✓":String(l.n).padStart(2,"0")}</span><span class="lesson-info"><strong>${l.title}</strong><small>${l.topicId} · ${l.focus}</small></span><span class="lesson-state">${done?"Completed":(l.review?"📝 Review":"Start →")}</span></button>${l.review?`<button class="review-row" data-review="${l.n}" ${completed<l.n?"disabled":""}>🧠 Review test · Lessons ${l.n-4}–${l.n} ${progress.tests[level+"-"+l.n]?"✓ Passed":""}</button>`:""}`}).join("");list.querySelectorAll("[data-lesson]").forEach(b=>b.addEventListener("click",()=>openLesson(b.dataset.lesson)));list.querySelectorAll("[data-review]").forEach(b=>b.addEventListener("click",()=>openReview(Number(b.dataset.review))))}
let activeLessonId="";function openLesson(id){const l=currentLessons().find(x=>x.id===id);if(!l)return;activeLessonId=id;setStudyScreen("lesson");$("lessonStudy").classList.remove("hidden");$("lessonMeta").textContent="LESSON "+l.n+" / 20 · "+levelDefs[l.level].en.toUpperCase();$("lessonTitle").textContent=l.title;$("lessonFeedback").textContent="";$("completeLesson").textContent=progress.lessons[id]?"✓ Completed — mark again":"✓ Mark lesson complete";$("lessonContent").innerHTML=`<p>${l.focus}. Learn each word, listen, then say it aloud.</p><div class="lesson-vocab">${l.words.map(w=>`<article class="lesson-word"><div class="hanzi small-hanzi">${w.h}</div><div class="pinyin">${w.p}</div><strong>${translateMeaning(w)}</strong><p>${w.e}</p><button class="secondary" data-lesson-audio="${w.h}">🔊 Listen</button><button class="outline" data-lesson-known="${w.h}">${progress.known.includes(w.h)?"✓ Learned":"Mark learned"}</button></article>`).join("")||"<p>Review your topic vocabulary, then complete the practice.</p>"}<div class="lesson-practice"><label for="lessonAnswer">Practice: type the Chinese word for “${l.words[0]?translateMeaning(l.words[0]):l.topic}”</label><input id="lessonAnswer" placeholder="Chinese characters"><p id="lessonAnswerFeedback" class="feedback"></p><button class="secondary" id="checkLessonAnswer">Check answer</button></div></div>`;$("lessonContent").querySelectorAll("[data-lesson-audio]").forEach(b=>b.onclick=()=>speak(b.dataset.lessonAudio));$("lessonContent").querySelectorAll("[data-lesson-known]").forEach(b=>b.onclick=()=>{let h=b.dataset.lessonKnown;if(!progress.known.includes(h))progress.known.push(h);save();b.textContent="✓ Learned";renderWord()});$("checkLessonAnswer").onclick=()=>{const w=l.words[0],answer=$("lessonAnswer").value.trim();$("lessonAnswerFeedback").textContent=w&&answer===w.h?"Correct! 很好！":"Try again: check the characters and listen once more."};document.getElementById("lessonStudy").scrollIntoView({behavior:"smooth",block:"start"})}
function openReview(n){const level=progress.settings.level||"beginner",key=level+"-"+n;setStudyScreen("test");const pool=currentLessons().filter(l=>l.n<=n&&l.n>n-5).flatMap(l=>l.words);const uniq=[...new Map(pool.map(w=>[w.h,w])).values()];const qs=(uniq.length?uniq:words.slice(0,8)).slice(0,5);$("reviewTest").classList.remove("hidden");$("testTitle").textContent="Review test · Lessons "+(n-4)+"–"+n;$("testFeedback").textContent="";$("submitTest").dataset.testKey=key;$("testContent").innerHTML=qs.map((w,i)=>{const opts=[w,...words.filter(x=>x.h!==w.h)].sort(()=>Math.random()-.5).slice(0,3).sort(()=>Math.random()-.5);return `<div class="test-question"><strong>${i+1}. ${translateMeaning(w)}</strong><div>${opts.map(o=>`<label><input type="radio" name="q${i}" value="${o.h}"> ${o.h} · ${o.p}</label>`).join("")}</div><input type="hidden" name="correct${i}" value="${w.h}"></div>`}).join("");$("submitTest").onclick=()=>{let score=0;qs.forEach((w,i)=>{const picked=document.querySelector(`input[name="q${i}"]:checked`);if(picked&&picked.value===w.h)score++});const passed=score>=Math.ceil(qs.length*.6);progress.tests[key]={score,total:qs.length,passed,date:new Date().toISOString()};save();$("testFeedback").textContent=`Score: ${score}/${qs.length}. ${passed?"Passed! Great progress.":"Keep practising and try again when ready."}`;renderLessons()};document.getElementById("reviewTest").scrollIntoView({behavior:"smooth",block:"start"})}
function startPlacement(){const sample=words.filter(w=>["你好","谢谢","多少钱？","我听不懂","工作","客户"].includes(w.h));let i=0,score=0;const host=$("placementResult");host.innerHTML=`<div class="placement-box"><p>Choose the correct meaning for each Chinese phrase.</p><div id="placementQuestion"></div><button class="primary" id="placementNext">Next question →</button></div>`;const render=()=>{if(i>=5){const lvl=score<=1?"beginner":score<=3?"intermediate":"advanced";progress.settings.level=lvl;save();$("levelSelect").value=lvl;host.innerHTML=`Result: ${score}/5 correct. Suggested level: <strong>${levelDefs[lvl].vi} · ${levelDefs[lvl].en}</strong>. Your 20-lesson path is ready.`;renderLessons();return}const w=sample[i],choices=[w,...words.filter(x=>x.h!==w.h).slice(i*3,i*3+3)].slice(0,4);$("placementQuestion").innerHTML=`<strong>${i+1}/5 · ${w.h} (${w.p})</strong>${choices.sort(()=>Math.random()-.5).map(c=>`<label class="test-option"><input type="radio" name="placement" value="${c.h}"> ${progress.settings.language==="vi"?(viMeanings[c.h]||c.m):c.m}</label>`).join("")}`;$("placementNext").textContent=i===4?"See my level":"Next question →"};$("placementNext").onclick=()=>{const chosen=document.querySelector('input[name="placement"]:checked');if(!chosen){host.querySelector("#placementQuestion").insertAdjacentHTML("beforeend","<p>Please choose an answer.</p>");return}if(chosen.value===sample[i].h)score++;i++;render()};render()}
function setStudyScreen(which){const lessonsCard=document.querySelector('[data-screen="lessons"]');const subnav=document.querySelector(".learning-subnav");const topicsCard=document.querySelector('[data-screen="topics"]');const planCard=document.querySelector('[data-screen="plan"]');const study=$("lessonStudy"),test=$("reviewTest");if(which==="lesson"){if(lessonsCard)lessonsCard.classList.remove("active");if(subnav)subnav.classList.add("hidden");if(topicsCard)topicsCard.classList.remove("active");if(planCard)planCard.classList.remove("active");study.classList.remove("hidden");test.classList.add("hidden");}else if(which==="test"){if(lessonsCard)lessonsCard.classList.remove("active");if(subnav)subnav.classList.add("hidden");if(topicsCard)topicsCard.classList.remove("active");if(planCard)planCard.classList.remove("active");study.classList.add("hidden");test.classList.remove("hidden");}else{study.classList.add("hidden");test.classList.add("hidden");if(subnav)subnav.classList.remove("hidden");setPathScreen("lessons");}}
function setupLearning(){if(!$('learning'))return;const st=progress.settings;$('learningLanguage').value=st.language||'vi';$('settingsLanguage').value=st.language||'vi';$('levelSelect').value=st.level||'beginner';$('frequencySelect').value=String(st.frequency||5);$('reminderEnabled').checked=!!st.reminderEnabled;$('reminderTime').value=st.reminderTime||'19:30';renderTopicChoices();renderLevelSwitch();setPathScreen("lessons");renderLessons();document.querySelectorAll("[data-path-screen]").forEach(b=>b.onclick=()=>setPathScreen(b.dataset.pathScreen));document.querySelectorAll("[data-level]").forEach(b=>b.onclick=()=>{st.level=b.dataset.level;currentUnit=1;$("levelSelect").value=st.level;save();renderLevelSwitch();renderLessons();applyWordFilters()});$('learningLanguage').onchange=()=>{st.language=$('learningLanguage').value;save();$('settingsLanguage').value=st.language;renderTopicChoices();renderLessons();renderWord()};$('settingsLanguage').onchange=()=>{$('learningLanguage').value=$('settingsLanguage').value;st.language=$('settingsLanguage').value;save();renderTopicChoices();renderLessons();renderWord()};$('levelSelect').onchange=()=>{st.level=$('levelSelect').value;currentUnit=1;save();renderLevelSwitch();renderLessons();applyWordFilters()};$('frequencySelect').onchange=()=>{st.frequency=Number($('frequencySelect').value);save()};$('selectAllTopics').onclick=()=>{st.topics=topicDefs.map(t=>t.id);save();renderTopicChoices();renderLessons()};$('placementStart').onclick=startPlacement;$('quickPlacement').onclick=()=>{setPathScreen('plan');startPlacement();document.getElementById('learning').scrollIntoView({behavior:'smooth',block:'start'})};$('backHome').onclick=()=>{setStudyScreen('list');switchTab('home');document.querySelector('.hero')?.scrollIntoView({behavior:'smooth',block:'start'})};$('settingsLevel').value=st.level||'beginner';$('settingsLevel').onchange=()=>{st.level=$('settingsLevel').value;currentUnit=1;$('levelSelect').value=st.level;save();renderLevelSwitch();renderLessons();applyWordFilters()};$('closeLesson').onclick=()=>setStudyScreen('list');$('backToLessons').onclick=()=>setStudyScreen('list');$('closeTest').onclick=()=>setStudyScreen('list');$('backFromTest').onclick=()=>setStudyScreen('list');$('completeLesson').onclick=()=>{const n=Number(($('lessonMeta').textContent.match(/LESSON (\d+)/)||[])[1]);const key=activeLessonId||((st.level||'beginner')+'-'+n);if(n){progress.lessons[key]=true;touchDay();$('lessonFeedback').textContent='Lesson saved! Your progress is stored on this device.';$('completeLesson').textContent='✓ Completed';renderLessons()}};$('saveReminder').onclick=()=>{st.reminderEnabled=$('reminderEnabled').checked;st.reminderTime=$('reminderTime').value||'19:30';save();const enabled=st.reminderEnabled;let status=enabled?'Reminder preference saved.':'Daily reminder turned off.';if(enabled&&window.NativeSpeech&&window.NativeSpeech.setDailyReminder){try{window.NativeSpeech.setDailyReminder(true,Number(st.reminderTime.split(':')[0]),Number(st.reminderTime.split(':')[1]));status='Daily reminder scheduled for '+st.reminderTime+'.'}catch(e){status='Saved, but Android could not schedule the reminder. Please rebuild/install the latest APK.'}}else if(enabled){if('Notification'in window){Notification.requestPermission().then(v=>{$('reminderStatus').textContent=v==='granted'?'Notifications allowed. For reliable reminders while the app is closed, use the Android APK with reminder support.':'Notification permission was not granted.'})}status='Preference saved. Web reminders may require the app to be open.'} $('reminderStatus').textContent=status};}
